const fs = require('fs');
const input = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < input.length && input[pos] <= 32) pos++;
  let value = 0;
  while (pos < input.length && input[pos] > 32) {
    value = value * 10 + input[pos] - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const K = nextInt();
const values = new Uint8Array(N);

for (let i = 0; i < N; i++) {
  values[i] = nextInt();
}

function countAtMost(limit) {
  if (limit < 0) return 0;

  let left = 0;
  let sum = 0;
  let count = 0;

  for (let right = 0; right < N; right++) {
    sum += values[right];

    while (sum > limit) {
      sum -= values[left++];
    }

    count += right - left + 1;
  }

  return count;
}

